import numpy as np
import pandas as pd
from pandas import SparseArray, SparseDtype

fills = [
    ("pd_NaT", pd.NaT),
    ("np_nan", np.nan),
    ("np_float64_nan", np.float64("nan")),
    ("pd_NA", pd.NA),
]
kinds = ("M8", "m8")
units = ("s", "ms", "us", "ns")

# SparseArray level: fill_value.dtype must equal the values' own dtype
arr_total = 0
arr_norm = 0
for kind in kinds:
    for unit in units:
        values = np.array([1, 2, 3], "i8").astype(f"{kind}[{unit}]")
        values[1] = "NaT"
        for _name, fill in fills:
            arr_total += 1
            try:
                arr = SparseArray(values, fill_value=fill)
                if arr.fill_value.dtype == values.dtype:
                    arr_norm += 1
            except Exception:
                pass

# SparseDtype level
dt_total = 0
dt_norm = 0
for kind in kinds:
    for unit in units:
        values = np.array([1], "i8").astype(f"{kind}[{unit}]")
        values[0] = "NaT"
        for _name, fill in fills:
            dt_total += 1
            try:
                d = SparseDtype(values.dtype, fill)
                if d.fill_value.dtype == values.dtype:
                    dt_norm += 1
            except Exception:
                pass

# right-kind, wrong-unit NaT must be normalized to the subtype's own unit
unit_total = 0
unit_norm = 0
for kind in kinds:
    for unit in units:
        d = np.dtype(f"{kind}[{unit}]")
        unit_total += 1
        try:
            got = SparseDtype(d, d.type("NaT", "10s")).fill_value.dtype
            if got == d:
                unit_norm += 1
        except Exception:
            pass

probe("arr_total", arr_total)
probe("arr_normalized", arr_norm)
probe("dtype_total", dt_total)
probe("dtype_normalized", dt_norm)
probe("unit_total", unit_total)
probe("unit_normalized", unit_norm)

# cross-kind NA fill must still be rejected
try:
    SparseDtype("M8[ns]", np.timedelta64("NaT"))
    probe("cross_kind_raises", 0)
except TypeError:
    probe("cross_kind_raises", 1)

buggy.sparse_dtype_na_fill_normalization:
import numpy as np
import pandas as pd
from pandas import SparseDtype

kinds = ["M8", "m8"]
units = ["s", "ms", "us", "ns"]
fills = [("NaT", pd.NaT), ("NAN", np.nan), ("F8NAN", np.float64("nan")), ("PDNA", pd.NA)]

recs = []
for kind in kinds:
    for unit in units:
        dt = np.dtype(kind + "[" + unit + "]")
        for nm, f in fills:
            try:
                d = SparseDtype(dt, f)
                v = 1.0 if d.fill_value.dtype == dt else 0.0
            except Exception:
                v = 0.0
            recs.append(("dtype_" + kind + "_" + unit + "_" + nm, v))

for kind in kinds:
    for unit in units:
        dt = np.dtype(kind + "[" + unit + "]")
        if kind == "M8":
            bad = np.datetime64("NaT", "10s")
        else:
            bad = np.timedelta64("NaT", "10s")
        try:
            d = SparseDtype(dt, bad)
            v = 1.0 if d.fill_value.dtype == dt else 0.0
        except Exception:
            v = 0.0
        recs.append(("dtype_wrongunit_" + kind + "_" + unit, v))

try:
    SparseDtype(np.dtype("M8[ns]"), np.timedelta64("NaT"))
    v = 0.0
except Exception:
    v = 1.0
recs.append(("dtype_crosskind_rejected", v))

for name, val in recs:
    probe(name, val)

buggy.sparse_array_fill_dtype_behavior:
import numpy as np
import pandas as pd
from pandas.arrays import SparseArray

kinds = ["M8", "m8"]
units = ["s", "ns"]
fills = [("NaT", pd.NaT), ("NAN", np.nan), ("F8NAN", np.float64("nan")), ("PDNA", pd.NA)]

recs = []
for kind in kinds:
    for unit in units:
        dt = np.dtype(kind + "[" + unit + "]")
        if kind == "M8":
            nat = np.datetime64("NaT")
        else:
            nat = np.timedelta64("NaT")
        values = np.array([1, 2, 3], dtype="i8").astype(dt)
        values[1] = nat
        allfill = np.array([nat, nat], dtype=dt)
        for nm, f in fills:
            fm = 0.0
            dm = 0.0
            tm = 0.0
            try:
                arr = SparseArray(values, fill_value=f)
                if arr.fill_value.dtype == dt:
                    fm = 1.0
                try:
                    if np.asarray(arr.to_dense()).dtype == dt:
                        dm = 1.0
                except Exception:
                    dm = 0.0
                try:
                    taken = SparseArray(allfill, fill_value=f).take([0, 1], allow_fill=True)
                    if taken.fill_value.dtype == dt:
                        tm = 1.0
                except Exception:
                    tm = 0.0
            except Exception:
                fm = 0.0
                dm = 0.0
                tm = 0.0
            recs.append(("arr_" + kind + "_" + unit + "_" + nm + "_fill", fm))
            recs.append(("arr_" + kind + "_" + unit + "_" + nm + "_dense", dm))
            recs.append(("arr_" + kind + "_" + unit + "_" + nm + "_take", tm))

for name, val in recs:
    probe(name, val)

